def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_d = sum(1 for m, o in history if o == 'D')
    opp_c = n - opp_d
    if opp_c == 0:
        return 'D'
    if n >= 2:
        last_me, last_opp = history[-1]
        prev_me = history[-2][0]
        if last_me == 'C' and last_opp == 'D' and prev_me == 'D':
            return 'C'
    if n >= 3:
        if history[-1] == ('D', 'D') and history[-2] == ('D', 'D') and history[-3] == ('D', 'D'):
            return 'C'
    if opp_d / n > 0.35:
        return 'D'
    return 'C'
